files.artifacts/business-owner/epic.artifact.s:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "gsmarc://saf/artifacts/epic.artifact/v1",
  "$ref": "gsmarc://saf/harness/contracts/artifact/v1",
  "title": "epic artifact schema",
  "type": "object",
  "additionalProperties": true,
  "x-artifact": {
    "id": "epic",
    "kind": "epic",
    "template": "templates/layers/portfolio/actors/business-owner/artifacts/epic.artifact-template.md",
    "pathPatterns": [
      "portfolio-backlog/*/*.epic.md"
    ],
    "sections": {
      "required": [
        "Overview"
      ],
      "optional": [
        "Strategic Themes",
        "Epics",
        "Implementation Notes",
        "Open Items"
      ],
      "maxDepth": 3,
      "allowUnknown": false
    },
    "type": "business"
  },
  "required": [
    "__path",
    "__kind",
    "__artifact_id",
    "__frontmatter_present",
    "status",
    "type",
    "title",
    "strategicTheme",
    "businessOwner",
    "enterpriseArchitect",
    "products",
    "workItemRelations",
    "wsjf",
    "mvpFeatures",
    "created",
    "openItems",
    "cost",
    "github"
  ],
  "properties": {
    "__path": {
      "description": "Workspace-relative path of the artifact file, injected by the orchestration harness (not authored in frontmatter).",
      "type": "string",
      "minLength": 1
    },
    "__kind": {
      "description": "Artifact-kind discriminator injected by the harness; must equal x-artifact.kind.",
      "const": "epic"
    },
    "__artifact_id": {
      "description": "Stable artifact id injected by the harness, derived from the file and frontmatter.",
      "type": "string",
      "minLength": 1
    },
    "__frontmatter_present": {
      "description": "Harness assertion that YAML frontmatter was found and parsed; always true for a valid artifact.",
      "const": true
    },
    "__sections": {
      "description": "Artifact body sections keyed by their `## ` heading \u2014 one property per template section; the value is the raw Markdown under that heading. Authored artifacts may add or omit sections, so this is advisory (additionalProperties is permitted) and no section is individually required.",
      "type": "object",
      "properties": {
        "Epic hypothesis statement": {
          "description": "Use exactly one hypothesis block in this canonical form",
          "type": "string"
        },
        "Outcome hypothesis & leading indicators": {
          "description": "`Leading indicator: <early measurable signal>`",
          "type": "string"
        },
        "In scope / out of scope": {
          "description": "Out (non-goals)",
          "type": "string"
        },
        "Portfolio outcome rationale": {
          "description": "Why this Epic matters to the portfolio in outcome terms.",
          "type": "string"
        },
        "Enterprise-Architect runway (EA hat)": {
          "description": "Cross-product architectural implications, NFR backbone, shared enablers, and which products must build runway. Enabler Epics live mostly here. May spawn product-level ADRs (those remain product-scoped, authored by `@system-architect`).",
          "type": "string"
        },
        "Affected products & Feature seeds": {
          "description": "Use one row per product seed in this form",
          "type": "string"
        },
        "MVP & pivot/persevere": {
          "description": "The smallest Feature set (`mvpFeatures`) that validates the hypothesis. After the MVP, the Business Owner decides pivot / persevere / stop at \u2605 Epic Gate review or Inspect & Adapt.",
          "type": "string"
        },
        "Dependencies / constraints": {
          "description": "Other Epics, external systems, regulations.",
          "type": "string"
        },
        "Work-item relations": {
          "description": "Use only relation types that change planning or governance behavior.",
          "type": "string"
        },
        "Open items": {
          "description": "The human-readable companion to the `openItems:` frontmatter ledger (the [open-item ledger](../../../../orchestrator/SKILL.md#open-item-ledger)) \u2014 this Epic's **clarifications** (proactive unknowns surfaced by the CE Discovery turn) and **challenges** (reactive findings from peer review), formal...",
          "type": "string"
        }
      },
      "additionalProperties": true
    },
    "__body": {
      "description": "Raw Markdown body of the artifact (everything after the frontmatter), injected by the harness.",
      "type": "string"
    },
    "status": {
      "description": "funnel | reviewing | analyzing | portfolio-backlog | implementing | done | blocked",
      "enum": [
        "funnel",
        "reviewing",
        "analyzing",
        "portfolio-backlog",
        "implementing",
        "done",
        "blocked"
      ]
    },
    "type": {
      "description": "Artifact type discriminator.",
      "enum": [
        "business"
      ]
    },
    "title": {
      "description": "Human-readable title of the artifact.",
      "type": "string",
      "minLength": 1
    },
    "workItemRelations": {
      "description": "Typed work-item relations (dependsOn / enables / relatedTo / supersedes).",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/workItemRelations"
    },
    "wsjf": {
      "description": "Weighted Shortest Job First scoring block.",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/wsjf"
    },
    "created": {
      "description": "Authoring date (YYYY-MM-DD).",
      "type": "string",
      "minLength": 1
    },
    "openItems": {
      "description": "clarification + challenge ledger \u2014 see orchestrator \"Open-item ledger\". Each entry: { id, kind, raised_by, owner, blocking, status, \u2026 }; kind: clarification | challenge. status: open | resolved | withdrawn. A blocking+open entry HALTS the \u2605 Epic Gate.",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/openItems"
    },
    "cost": {
      "description": "token cost accounting \u2014 see the cost-snapshot invariant instructions",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/cost"
    },
    "github": {
      "description": "filled by portfolio/_sync (Portfolio Project); null when authoring",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/githubSync"
    },
    "strategicTheme": {
      "description": "see strategic-themes.artifact-template.md",
      "type": "string",
      "minLength": 1
    },
    "businessOwner": {
      "description": "the BO-hat approver (you)",
      "type": "string",
      "minLength": 1
    },
    "enterpriseArchitect": {
      "description": "the EA-hat owner of the runway (you)",
      "type": "string",
      "minLength": 1
    },
    "products": {
      "description": "product slugs this Epic spans (>=1); cross-product is allowed HERE only",
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 1
    },
    "mvpFeatures": {
      "description": "Feature ids that constitute the MVP (the pivot/persevere test)",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "sources": {
      "description": "Derivation provenance (narrowed subtype of the base contract's sources): refs to the upstream artifact(s) this epic was built from. Allowed source kinds: strategic-themes.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "pattern": "(^|/)([a-z0-9-]+\\.)?(strategic-themes)\\.md$"
      }
    }
  }
}

