{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "gsmarc://saf/artifacts/lean-business-case.artifact/v1",
  "$ref": "gsmarc://saf/harness/contracts/artifact/v1",
  "title": "lean-business-case artifact schema",
  "description": "Validates the Markdown Lean Business Case artifact for an Epic. Authored in the Epic Lean Business Case practice; challenged by @enterprise-architect and @security-expert; weighed by the Central Supervisor at the \u2605 Epic Gate.",
  "type": "object",
  "additionalProperties": true,
  "x-artifact": {
    "id": "lean-business-case",
    "kind": "lean-business-case",
    "template": "templates/layers/portfolio/actors/business-owner/artifacts/lean-business-case.artifact-template.md",
    "pathPatterns": [
      "portfolio-backlog/*/*.lean-business-case.md"
    ],
    "sections": {
      "required": [
        "Problem & opportunity",
        "Solution hypothesis (MVP)",
        "WSJF",
        "Leading & lagging indicators",
        "Cost / effort estimate",
        "Enabler / runway dependency",
        "Pivot / persevere / stop criteria",
        "Challenge findings"
      ],
      "optional": [],
      "maxDepth": 2,
      "allowUnknown": false
    },
    "renderOnly": false
  },
  "required": [
    "__path",
    "__kind",
    "__artifact_id",
    "__frontmatter_present",
    "epic",
    "status",
    "slug",
    "title"
  ],
  "properties": {
    "__path": {
      "description": "Workspace-relative path of the artifact file, injected by the orchestration harness (not authored in frontmatter).",
      "type": "string",
      "minLength": 1
    },
    "__kind": {
      "description": "Artifact-kind discriminator injected by the harness; must equal x-artifact.kind.",
      "const": "lean-business-case"
    },
    "__artifact_id": {
      "description": "Stable artifact id injected by the harness, derived from the file and frontmatter.",
      "type": "string",
      "minLength": 1
    },
    "__frontmatter_present": {
      "description": "Harness assertion that YAML frontmatter was found and parsed; always true for a valid artifact.",
      "const": true
    },
    "__sections": {
      "description": "Artifact body sections keyed by their `## ` heading \u2014 one property per template section; the value is the raw Markdown under that heading.",
      "type": "object",
      "properties": {
        "Problem & opportunity": {
          "description": "The systemic problem, who has it, why now.",
          "type": "string"
        },
        "Solution hypothesis (MVP)": {
          "description": "The smallest Feature set that tests the hypothesis.",
          "type": "string"
        },
        "WSJF": {
          "description": "Weighted Shortest Job First scoring block.",
          "type": "string"
        },
        "Leading & lagging indicators": {
          "description": "Early measurable signals and outcome metrics.",
          "type": "string"
        },
        "Cost / effort estimate": {
          "description": "Rough order of magnitude; informs Participatory Budgeting.",
          "type": "string"
        },
        "Enabler / runway dependency": {
          "description": "Architectural-runway items this Epic consumes or requires.",
          "type": "string"
        },
        "Pivot / persevere / stop criteria": {
          "description": "Evidence that would change the decision.",
          "type": "string"
        },
        "Challenge findings": {
          "description": "EA / Security adversarial notes, folded in before the \u2605 Epic Gate.",
          "type": "string"
        }
      },
      "additionalProperties": true
    },
    "__body": {
      "description": "Raw Markdown body of the artifact (everything after the frontmatter), injected by the harness.",
      "type": "string"
    },
    "epic": {
      "description": "Id of the Epic this lean business case shapes (e.g. E-1).",
      "type": "string",
      "minLength": 1
    },
    "status": {
      "description": "Authoring lifecycle of the business case.",
      "enum": [
        "draft",
        "challenged",
        "gate-ready"
      ]
    },
    "fundingState": {
      "description": "Funding posture proposed by the case (set by Participatory Budgeting).",
      "enum": [
        "proposed",
        "funded",
        "not-funded"
      ]
    },
    "slug": {
      "$ref": "gsmarc://saf/harness/contracts/slugs/v1#/definitions/artifactSlug",
      "description": "URL-safe slug for the artifact (e.g. e-1-lbc)."
    },
    "title": {
      "description": "Human-readable title for the lean business case.",
      "type": "string",
      "minLength": 1
    },
    "workItemRelations": {
      "description": "Typed work-item relations (dependsOn / enables / relatedTo / supersedes).",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/workItemRelations"
    },
    "wsjf": {
      "description": "Weighted Shortest Job First scoring block.",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/wsjf"
    },
    "openItems": {
      "description": "Clarification + challenge ledger (a blocking open entry halts the relevant gate).",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/openItems"
    },
    "cost": {
      "description": "Token-cost accounting block (see the cost definition).",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/cost"
    },
    "github": {
      "description": "GitHub Projects sync envelope, filled by portfolio/_sync (null when authoring).",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/githubSync"
    },
    "sources": {
      "description": "Derivation provenance (narrowed subtype of the base contract's sources): refs to the upstream artifact(s) this lean-business-case was built from. Allowed source kinds: epic, epic-enabler.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "pattern": "(^|/)([a-z0-9-]+\\.)?(epic|epic-enabler)\\.md$"
      }
    }
  }
}

