{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "gsmarc://saf/artifacts/feasibility-review.artifact/v1",
  "$ref": "gsmarc://saf/harness/contracts/artifact/v1",
  "title": "feasibility-review artifact schema",
  "type": "object",
  "additionalProperties": true,
  "definitions": {
    "findings": {
      "description": "Implementation-feasibility / technical-risk findings raised by the review (each an object: id, severity, finding, recommendation).",
      "type": "array",
      "items": {
        "type": "object"
      }
    }
  },
  "x-artifact": {
    "id": "feasibility-review",
    "kind": "feasibility-review",
    "template": "templates/layers/team/actors/developer/artifacts/feasibility-review.artifact-template.md",
    "pathPatterns": [
      "portfolio/budget-allocation.feasibility-review.md",
      "portfolio/portfolio-backlog/*/*.feasibility-review.md",
      "art/*/program-backlog/*/*.feasibility-review.md",
      "art/*/pi-*/objectives.feasibility-review.md",
      "art/*/pi-*/iterations/*/plan.feasibility-review.md",
      "art/*/teams/*/team-backlog/*/*.feasibility-review.md"
    ],
    "renderOnly": false
  },
  "required": [
    "__path",
    "__kind",
    "__artifact_id",
    "__frontmatter_present"
  ],
  "properties": {
    "__path": {
      "description": "Workspace-relative path of the artifact file, injected by the harness.",
      "type": "string",
      "minLength": 1
    },
    "__kind": {
      "description": "Artifact-kind discriminator injected by the harness; must equal x-artifact.kind.",
      "const": "feasibility-review"
    },
    "__artifact_id": {
      "description": "Stable artifact id injected by the harness.",
      "type": "string",
      "minLength": 1
    },
    "__frontmatter_present": {
      "description": "Harness assertion that YAML frontmatter was found and parsed.",
      "type": "boolean"
    },
    "__sections": {
      "description": "Artifact body sections keyed by their `## ` heading (advisory; additionalProperties permitted).",
      "type": "object",
      "properties": {
        "Subject under review": {
          "description": "Link / id of what is reviewed; restate the scope.",
          "type": "string"
        },
        "Findings": {
          "description": "Severity-graded feasibility findings table.",
          "type": "string"
        },
        "Verdict": {
          "description": "PASS | CONCERNS | FAIL.",
          "type": "string"
        },
        "Recommendations": {
          "description": "Remediation guidance for the owner.",
          "type": "string"
        }
      },
      "additionalProperties": true
    },
    "__body": {
      "description": "Raw Markdown body, injected by the harness.",
      "type": "string"
    },
    "title": {
      "description": "Human-readable title.",
      "type": "string",
      "minLength": 1
    },
    "subject": {
      "description": "The artifact id or path under review.",
      "type": "string",
      "minLength": 1
    },
    "reviewer": {
      "description": "The reviewing agent handle (`@developer`).",
      "type": "string",
      "minLength": 1
    },
    "verdict": {
      "description": "Review verdict.",
      "enum": [
        "pass",
        "concerns",
        "fail"
      ]
    },
    "created": {
      "description": "Authoring date (YYYY-MM-DD).",
      "type": "string",
      "minLength": 1
    },
    "findings": {
      "description": "Feasibility / implementation-risk findings.",
      "$ref": "#/definitions/findings"
    },
    "openItems": {
      "description": "Open-item ledger.",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/openItems"
    },
    "sources": {
      "description": "Derivation provenance (narrowed subtype of the base contract's sources): refs to the upstream artifact(s) this feasibility-review was built from.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "pattern": "(^|/)([a-z0-9-]+\\.)?(epic|epic-enabler|lean-business-case|budget-allocation|feature|feature-enabler|story|story-enabler|objectives|plan|adr|nfr-list|architecture-runway|architecture-vision)\\.md$"
      }
    }
  }
}

