files.artifacts/framework-definitions.schema.j:
{
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "gsmarc://saf/artifacts/framework-definitions/v1",
    "title": "SAFe methodology reusable definitions",
    "description": "Reusable JSON Schema definitions used by the SAFe methodology artifact schemas in this framework. These are not part of the generic harness base schema because they encode methodology-specific or host-specific concepts (WSJF, GitHub Projects sync, token-cost accounting).",
    "type": "object",
    "definitions": {
        "workItemRelations": {
            "description": "Typed work-item relations between artifacts.",
            "type": "object",
            "additionalProperties": true,
            "properties": {
                "dependsOn": {
                    "description": "Hard prerequisite artifact ids that must advance or land before this item.",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "enables": {
                    "description": "Artifact ids this item intentionally makes possible or materially easier.",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "relatedTo": {
                    "description": "Non-gating semantic or strategic links; never use as a hidden dependency list.",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "supersedes": {
                    "description": "Artifact ids intentionally replaced by this item.",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                }
            }
        },
        "wsjf": {
            "description": "Weighted Shortest Job First scoring block used to rank the backlog.",
            "type": "object",
            "additionalProperties": true,
            "required": [
                "userBusinessValue",
                "timeCriticality",
                "riskReduction",
                "jobSize",
                "score"
            ],
            "properties": {
                "userBusinessValue": {
                    "description": "Relative user/business value of the work item.",
                    "type": "number"
                },
                "timeCriticality": {
                    "description": "How time-sensitive the value is (it decays if delayed).",
                    "type": "number"
                },
                "riskReduction": {
                    "description": "Risk reduction / opportunity enablement value.",
                    "type": "number"
                },
                "jobSize": {
                    "description": "Relative size/effort of the job (the WSJF denominator).",
                    "type": "number"
                },
                "score": {
                    "description": "Computed WSJF score = (userBusinessValue + timeCriticality + riskReduction) / jobSize.",
                    "type": "number"
                }
            }
        },
        "cost": {
            "description": "Token-cost accounting block.",
            "type": "object",
            "additionalProperties": true,
            "required": [
                "tokensIn",
                "tokensOut",
                "tokensCached",
                "tokensSelf",
                "tokensRolled",
                "dispatches",
                "source",
                "committed"
            ],
            "properties": {
                "tokensIn": {
                    "description": "NET-NEW prompt tokens = sum(inputTokens - cachedTokens) of this item's dispatches.",
                    "type": "number"
                },
                "tokensOut": {
                    "description": "Sum of outputTokens of those dispatches.",
                    "type": "number"
                },
                "tokensCached": {
                    "description": "Sum of cachedTokens (re-sent context); excluded from tokensSelf, kept for billed-cost reconstruction.",
                    "type": "number"
                },
                "tokensSelf": {
                    "description": "tokensIn + tokensOut - the item's own net cost.",
                    "type": "number"
                },
                "tokensRolled": {
                    "description": "tokensSelf plus the rolled cost of child items - the item's end-to-end cost.",
                    "type": "number"
                },
                "dispatches": {
                    "description": "Number of subagent dispatches counted into tokensSelf (not llm_request turns).",
                    "type": "number"
                },
                "source": {
                    "description": "Provenance of the cost figures: measured, estimated, or mixed.",
                    "enum": [
                        "measured",
                        "estimated",
                        "mixed"
                    ]
                },
                "committed": {
                    "description": "YYYY-MM-DD the one-time cost snapshot was written; immutable after (null until committed).",
                    "type": [
                        "string",
                        "null"
                    ]
                }
            }
        },
        "githubSync": {
            "description": "GitHub Projects sync envelope; filled by portfolio/_sync, null when authoring.",
            "type": "object",
            "additionalProperties": true,
            "properties": {
                "issueNumber": {
                    "description": "GitHub issue number; filled by portfolio/_sync, null when authoring.",
                    "type": [
                        "integer",
                        "number",
                        "string",
                        "null"
                    ]
                },
                "issueNodeId": {
                    "description": "GitHub issue node id; filled by portfolio/_sync, null when authoring.",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "projectItemId": {
                    "description": "GitHub Projects item id; filled by portfolio/_sync, null when authoring.",
                    "type": [
                        "string",
                        "null"
                    ]
                }
            }
        },
        "openItems": {
            "description": "Clarification + challenge ledger entries (each an object: id, kind, raised_by, owner, blocking, status, ...).",
            "type": "array",
            "items": {
                "type": "object"
            }
        }
    }
}

