{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "gsmarc://saf/artifacts/feature.artifact/v1",
  "$ref": "gsmarc://saf/harness/contracts/artifact/v1",
  "title": "feature artifact schema",
  "type": "object",
  "additionalProperties": true,
  "x-artifact": {
    "id": "feature",
    "kind": "feature",
    "template": "templates/layers/program/actors/product-manager/artifacts/feature.artifact-template.md",
    "pathPatterns": [
      "art/*/program-backlog/*/*.feature.md"
    ],
    "sections": {
      "required": [
        "Overview"
      ],
      "optional": [
        "User Stories",
        "Acceptance Criteria",
        "Open Items"
      ],
      "maxDepth": 2,
      "allowUnknown": false
    },
    "type": "business"
  },
  "required": [
    "__path",
    "__kind",
    "__artifact_id",
    "__frontmatter_present",
    "status",
    "type",
    "title",
    "parentEpic",
    "epicRationale",
    "workItemRelations",
    "wsjf",
    "structurant",
    "architectureInventory",
    "adrs",
    "owner",
    "created",
    "openItems",
    "cost",
    "github"
  ],
  "properties": {
    "__path": {
      "description": "Workspace-relative path of the artifact file, injected by the orchestration harness (not authored in frontmatter).",
      "type": "string",
      "minLength": 1
    },
    "__kind": {
      "description": "Artifact-kind discriminator injected by the harness; must equal x-artifact.kind.",
      "const": "feature"
    },
    "__artifact_id": {
      "description": "Stable artifact id injected by the harness, derived from the file and frontmatter.",
      "type": "string",
      "minLength": 1
    },
    "__frontmatter_present": {
      "description": "Harness assertion that YAML frontmatter was found and parsed; always true for a valid artifact.",
      "const": true
    },
    "__sections": {
      "description": "Artifact body sections keyed by their `## ` heading \u2014 one property per template section; the value is the raw Markdown under that heading. Authored artifacts may add or omit sections, so this is advisory (additionalProperties is permitted) and no section is individually required.",
      "type": "object",
      "properties": {
        "Description": {
          "description": "What is this Feature, in one paragraph.",
          "type": "string"
        },
        "Acceptance criteria": {
          "description": "Use one flat bullet per criterion, labeled `AC1`, `AC2`, `AC3`",
          "type": "string"
        },
        "Benefit hypothesis": {
          "description": "Why this Feature delivers value (a slice of the parent Epic's outcome hypothesis, or the Feature's own rationale when standalone).",
          "type": "string"
        },
        "NFR applicability / trace": {
          "description": "List the canonical product NFRs from `products/<product-slug>/nfr-list.md` that apply to this Feature, plus any Feature-specific tightening or derived verification notes. Do not redefine the product's canonical NFR set here. A missing NFR is a runway concern, not Feature AC.",
          "type": "string"
        },
        "Routing classification": {
          "description": "Risk: low | medium | critical \u2014 consequence of being wrong.",
          "type": "string"
        },
        "Dependencies": {
          "description": "Other Features, ADRs, external systems. Cross-product coordination is expressed via the shared parent Epic (one Feature per product), never a single cross-product Feature.",
          "type": "string"
        },
        "Work-item relations": {
          "description": "Use typed work-item relations only when they affect flow, decomposition, or governance.",
          "type": "string"
        },
        "Architecture decision inventory": {
          "description": "If `structurant: true`, point to the committed architecture inventory artifact that tracks the Feature's decision units, their coverage state, linked ADRs, waivers, and enabler follow-up. If `structurant: false`, set `architectureInventory: null` and omit this section.",
          "type": "string"
        },
        "Open items": {
          "description": "The human-readable companion to the `openItems:` frontmatter ledger (the [open-item ledger](../../orchestrator/SKILL.md#open-item-ledger)) \u2014 this Feature's **clarifications** (proactive unknowns surfaced by the CE Discovery turn) and **challenges** (reactive findings from peer review), for...",
          "type": "string"
        },
        "Story breakdown (filled in step 6 by PO)": {
          "description": "`Story breakdown (filled in step 6 by PO)` section of the artifact body.",
          "type": "string"
        }
      },
      "additionalProperties": true
    },
    "__body": {
      "description": "Raw Markdown body of the artifact (everything after the frontmatter), injected by the harness.",
      "type": "string"
    },
    "status": {
      "description": "funnel | refined | arch-pending | ready | committed | in-progress | done | blocked",
      "enum": [
        "funnel",
        "refined",
        "arch-pending",
        "ready",
        "committed",
        "in-progress",
        "done",
        "blocked"
      ]
    },
    "type": {
      "description": "Artifact type discriminator.",
      "enum": [
        "business"
      ]
    },
    "title": {
      "description": "Human-readable title of the artifact.",
      "type": "string",
      "minLength": 1
    },
    "workItemRelations": {
      "description": "Typed work-item relations (dependsOn / enables / relatedTo / supersedes).",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/workItemRelations"
    },
    "wsjf": {
      "description": "Weighted Shortest Job First scoring block.",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/wsjf"
    },
    "created": {
      "description": "Authoring date (YYYY-MM-DD).",
      "type": "string",
      "minLength": 1
    },
    "openItems": {
      "description": "clarification + challenge ledger \u2014 see orchestrator \"Open-item ledger\". Each entry: { id, kind, raised_by, owner, blocking, status, \u2026 }; kind: clarification | challenge. status: open | resolved | withdrawn. A blocking+open entry HALTS the \u2605 Feature/Architecture Gate.",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/openItems"
    },
    "cost": {
      "description": "token cost accounting \u2014 see the cost-snapshot invariant instructions",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/cost"
    },
    "github": {
      "description": "filled by portfolio/_sync (GitHub Projects board sync); null when authoring",
      "$ref": "gsmarc://saf/artifacts/framework-definitions/v1#/definitions/githubSync"
    },
    "parentEpic": {
      "description": "portfolio Epic id, or null for a standalone Feature",
      "type": [
        "string",
        "null"
      ]
    },
    "epicRationale": {
      "description": "Why this Feature belongs to its parent Epic.",
      "type": "string",
      "minLength": 1
    },
    "structurant": {
      "description": "true \u21d2 requires architecture decisions (one or more ADRs) \u21d2 arch-pending",
      "type": "boolean"
    },
    "architectureInventory": {
      "description": "required when structurant=true; path to architecture/decision-inventory-F-N-*.md",
      "type": [
        "string",
        "null"
      ]
    },
    "adrs": {
      "description": "ADR ids referenced; may contain multiple decisions for one structurant Feature",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "pi": {
      "description": "set on transition to `committed`",
      "type": [
        "integer",
        "number",
        "string",
        "null"
      ]
    },
    "owner": {
      "description": "Accountable owner role/hat for this artifact.",
      "type": "string",
      "minLength": 1
    },
    "sources": {
      "description": "Derivation provenance (narrowed subtype of the base contract's sources): refs to the upstream artifact(s) this feature was built from. Allowed source kinds: epic, lean-business-case.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "pattern": "(^|/)([a-z0-9-]+\\.)?(epic|lean-business-case)\\.md$"
      }
    }
  }
}

